  const user = { id: 'u5', name: 'Eli', webhookUrl: 'https://hooks.example.com/u5' };
  const result = await notifier.send(user, message);

  assert.equal(result.status, 'sent');
  assert.equal(log[0].channel, 'webhook');
  assert.equal(log[0].title, 'Hi Eli');
  assert.equal(log[0].metadata.category, 'release');
  assert.equal(log[0].url, 'https://hooks.example.com/u5');
  assert.equal(log[0].method, 'POST');
  assert.deepEqual(log[0].headers, { 'content-type': 'application/json' });
  assert.equal(
    log[0].json,
    JSON.stringify({ title: 'Hi Eli', body: 'Update for u5', category: 'release', userId: 'u5' })
  );

  await notifier.send(user, { title: 'T', body: 'B' });
  assert.equal(JSON.parse(log[1].json).category, 'general');
});

test('webhook defaults to 10 sends per hour and honours maxPerHour', async () => {
  const user = { id: 'u5', webhookUrl: 'https://hooks.example.com/u5' };
  const message = { title: 'T', body: 'B' };
  const now = () => new Date('2026-01-02T00:00:00.000Z');

  const byDefault = createNotifier('webhook', { transport: transportWithLog([]), throttleStore: new Map(), now });
  for (let i = 0; i < 10; i++) {
    assert.equal((await byDefault.send(user, message)).status, 'sent');
  }
  const blocked = await byDefault.send(user, message);
  assert.equal(blocked.status, 'throttled');
  assert.match(blocked.reason, /webhook hourly limit/);

  const custom = createNotifier('webhook', { transport: transportWithLog([]), throttleStore: new Map(), now, maxPerHour: 2 });
  await custom.send(user, message);
  await custom.send(user, message);
  assert.equal((await custom.send(user, message)).status, 'throttled');
});

test('webhook send fails when the transport is not configured', async () => {
  const notifier = createNotifier('webhook', { transport: {}, throttleStore: new Map() });
  await assert.rejects(
    () => notifier.send({ id: 'u5', webhookUrl: 'https://hooks.example.com/u5' }, { title: 'T', body: 'B' }),
    error => error instanceof Error && error.message === 'webhook transport is not configured'
  );
});
